var o=[{title:`Porque os ombros variam`,text:`O ombro tem uma grande amplitude de movimento e depende de muitos músculos para se manter estável. Alcançar acima da cabeça, as posições profundas de press e os movimentos rápidos podem sentir-se muito diferentes de pessoa para pessoa. Um movimento que está restringido ou doloroso diz-lhe algo sobre os exercícios a escolher. Não prova que tem uma lesão específica.`},{title:`Ajuste o exercício`,text:`Se um press acima da cabeça com barra o incomodar, experimente um press com halteres em pega neutra, uma remada com apoio ou uma flexão na parede. Altere a profundidade ou a direção antes de acrescentar resistência. Os exercícios de puxar são um bom par para os press, mas nenhuma proporção fixa de empurrar e puxar cura a dor no ombro.`},{title:`Controlo e exposição gradual`,text:`Enquanto aprende um movimento, use repetições lentas e controladas, uma amplitude confortável e cargas leves. Desenvolver a força do ombro pode exigir um trabalho gradualmente mais difícil, mas essa progressão não deve agravar os sintomas. Forçar um alongamento através da dor ou testar levantamentos pesados acima da cabeça vezes sem conta não o levará lá mais depressa.`},{title:`Sinais de alerta`,text:`Procure aconselhamento médico rapidamente em caso de dor intensa depois de uma queda, um braço que não consegue mover, uma deformidade visível, inchaço importante ou dormência nova que não passa. Os sintomas que não melhoram também precisam de ser vistos por um profissional.`},{title:`Usar o TrainUp`,text:`Acrescente o ombro nas limitações do Perfil, com notas, e mantenha a lista de equipamento atualizada. O plano escolhe então apenas exercícios que se adaptam às suas limitações, equipamento, nível e coordenação. Se um exercício doer durante um treino, toque em «Sinto dor» para o terminar de imediato. Fica fora dos seus planos até o retomar no Perfil. Trocar exercícios desta forma não trata o conflito subacromial, a doença do manguito rotador nem qualquer outra condição específica.`}];var s=[{label:`NHS: dor no ombro e sinais de alerta`,url:`https://www.nhs.uk/symptoms/shoulder-pain/`},{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:o,sources:s};export{r as default,o as sections,s as sources};